    public sealed class PostMilestoneInvariant { public PostMilestoneInvariant(string invariantId, string playerSurface, string requiredBehavior, string regressionSignal) { InvariantId = invariantId ?? string.Empty; PlayerSurface = playerSurface ?? string.Empty; RequiredBehavior = requiredBehavior ?? string.Empty; RegressionSignal = regressionSignal ?? string.Empty; } public string InvariantId { get; } public string PlayerSurface { get; } public string RequiredBehavior { get; } public string RegressionSignal { get; } }
