    public sealed class PlayableSlicePostMilestoneStabilization
    {
        private static readonly string[] Required = { "HomeAlwaysReachable", "HiveStateReadable", "OnePrimaryIntentVisible", "BlockedActionExplained", "Demo500ReserveShownInternally", "NoLiveRuntimeClaim" };
        public PlayableSlicePostMilestoneStabilization(string id, IReadOnlyList<PostMilestoneInvariant> invariants, IReadOnlyList<PostMilestoneReserve> reserves) { Id = ColonyIntegrationIds.Require(id); Invariants = invariants ?? Array.Empty<PostMilestoneInvariant>(); Reserves = reserves ?? Array.Empty<PostMilestoneReserve>(); Verdict = EvaluateVerdict(); }
        public string Id { get; } public IReadOnlyList<PostMilestoneInvariant> Invariants { get; } public IReadOnlyList<PostMilestoneReserve> Reserves { get; } public PostMilestoneStabilityVerdict Verdict { get; }
        private PostMilestoneStabilityVerdict EvaluateVerdict() { if (Required.Any(r => Invariants.All(i => !ActivationReadinessText.Same(i.InvariantId, r)))) return PostMilestoneStabilityVerdict.BlockedByRegression; if (Invariants.Any(i => ActivationReadinessText.Contains(i.RegressionSignal, "live"))) return PostMilestoneStabilityVerdict.BlockedByLiveClaim; return Reserves.Count > 0 ? PostMilestoneStabilityVerdict.StableWithReserves : PostMilestoneStabilityVerdict.StableForNextReadinessLot; }
    }

    public sealed class MobileRouteFriction { public MobileRouteFriction(string routeId, string entryPoint, string exitPath, string frictionReason, int severity) { RouteId = routeId ?? string.Empty; EntryPoint = entryPoint ?? string.Empty; ExitPath = exitPath ?? string.Empty; FrictionReason = frictionReason ?? string.Empty; Severity = severity; } public string RouteId { get; } public string EntryPoint { get; } public string ExitPath { get; } public string FrictionReason { get; } public int Severity { get; } }
    public sealed class MobileNavigationRecommendation { public MobileNavigationRecommendation(string recommendationId, string text) { RecommendationId = recommendationId ?? string.Empty; Text = text ?? string.Empty; } public string RecommendationId { get; } public string Text { get; } }
    public sealed class MobileNavigationFrictionAudit
    {
        public MobileNavigationFrictionAudit(string id, IReadOnlyList<MobileRouteFriction> routeFrictions, IReadOnlyList<MobileNavigationRecommendation> recommendations) { Id = ColonyIntegrationIds.Require(id); RouteFrictions = routeFrictions ?? Array.Empty<MobileRouteFriction>(); Recommendations = recommendations ?? Array.Empty<MobileNavigationRecommendation>(); Verdict = EvaluateVerdict(); }
        public string Id { get; } public IReadOnlyList<MobileRouteFriction> RouteFrictions { get; } public IReadOnlyList<MobileNavigationRecommendation> Recommendations { get; } public MobileNavigationAuditVerdict Verdict { get; }
        private MobileNavigationAuditVerdict EvaluateVerdict() { if (RouteFrictions.Any(f => string.IsNullOrWhiteSpace(f.ExitPath) || ActivationReadinessText.Contains(f.FrictionReason, "MissingBackPath"))) return MobileNavigationAuditVerdict.BlockedByMissingBackPath; if (RouteFrictions.Any(f => ActivationReadinessText.Contains(f.FrictionReason, "live") || ActivationReadinessText.Contains(f.FrictionReason, "DuplicatePrimaryAction"))) return MobileNavigationAuditVerdict.BlockedByLiveConfusion; return RouteFrictions.Any(f => f.Severity >= 3) || Recommendations.Count > 0 ? MobileNavigationAuditVerdict.NeedsUiClarification : MobileNavigationAuditVerdict.Acceptable; }
    }

    public sealed class HiveActionActivationCandidate { public HiveActionActivationCandidate(string actionId, string playerIntent, string requiredPreviewProof, string futureAuthorityOwner, string activationRisk) { ActionId = actionId ?? string.Empty; PlayerIntent = playerIntent ?? string.Empty; RequiredPreviewProof = requiredPreviewProof ?? string.Empty; FutureAuthorityOwner = futureAuthorityOwner ?? string.Empty; ActivationRisk = activationRisk ?? string.Empty; } public string ActionId { get; } public string PlayerIntent { get; } public string RequiredPreviewProof { get; } public string FutureAuthorityOwner { get; } public string ActivationRisk { get; } }
