    public sealed class HiveActionActivationCandidateRegistry
    {
        private static readonly string[] Required = { "UpgradeRoom", "PlaceConstruction", "QueueProduction", "AssignWorker", "ResolveShortage", "PrepareDefense", "SelectResearch", "ReviewRecapAction" };
        public HiveActionActivationCandidateRegistry(string id, IReadOnlyList<HiveActionActivationCandidate> candidates, IReadOnlyList<HiveActionActivationBlocker> blockers) { Id = ColonyIntegrationIds.Require(id); Candidates = candidates ?? Array.Empty<HiveActionActivationCandidate>(); Blockers = blockers ?? Array.Empty<HiveActionActivationBlocker>(); Readiness = EvaluateReadiness(); }
        public string Id { get; } public IReadOnlyList<HiveActionActivationCandidate> Candidates { get; } public IReadOnlyList<HiveActionActivationBlocker> Blockers { get; } public HiveActionActivationReadiness Readiness { get; }
        private HiveActionActivationReadiness EvaluateReadiness() { if (Required.Any(r => Candidates.All(c => !ActivationReadinessText.Same(c.ActionId, r)))) return HiveActionActivationReadiness.NeedsUiClarification; if (Candidates.Any(c => string.IsNullOrWhiteSpace(c.FutureAuthorityOwner))) return HiveActionActivationReadiness.NeedsServerSpecification; if (Blockers.Any(b => ActivationReadinessText.Contains(b.Reason, "economy"))) return HiveActionActivationReadiness.BlockedByEconomyRisk; if (Blockers.Count > 0) return HiveActionActivationReadiness.BlockedByQaRisk; return HiveActionActivationReadiness.ReadyForDesign; }
    }

