    public sealed class ActivationReadinessLotClosureGate
    {
        private static readonly string[] RequiredLanes = { "BuilderImplementation", "ServerImpactReview", "UiMobileReview", "QaLotValidation", "Demo600Followup", "ArchitectDecision" };
        public ActivationReadinessLotClosureGate(string id, IReadOnlyList<ActivationClosureLedgerRow> ledgerRows, IReadOnlyList<ActivationClosureTeamLane> teamLanes, IReadOnlyList<ActivationClosureReserve> openReserves, Bee521BlockerStatus bee521Status) { Id = ColonyIntegrationIds.Require(id); LedgerRows = ledgerRows ?? Array.Empty<ActivationClosureLedgerRow>(); TeamLanes = teamLanes ?? Array.Empty<ActivationClosureTeamLane>(); OpenReserves = openReserves ?? Array.Empty<ActivationClosureReserve>(); Bee521Status = bee521Status; Verdict = EvaluateVerdict(); }
        public string Id { get; } public IReadOnlyList<ActivationClosureLedgerRow> LedgerRows { get; } public IReadOnlyList<ActivationClosureTeamLane> TeamLanes { get; } public IReadOnlyList<ActivationClosureReserve> OpenReserves { get; } public ActivationReadinessLotVerdict Verdict { get; } public Bee521BlockerStatus Bee521Status { get; }
        private ActivationReadinessLotVerdict EvaluateVerdict()
        {
            if (Bee521Status == Bee521BlockerStatus.ReleasedByFutureArchitectDecision) return ActivationReadinessLotVerdict.BlockedByBee521Premature;
            for (int bee = 501; bee <= 519; bee++) if (LedgerRows.All(r => !ActivationReadinessText.Same(r.SourceBee, "BEE-" + bee))) return ActivationReadinessLotVerdict.BlockedByMissingEvidence;
            if (RequiredLanes.Any(lane => TeamLanes.All(t => !ActivationReadinessText.Same(t.LaneId, lane) || !t.Assigned))) return ActivationReadinessLotVerdict.NeedsTeamRevision;
            if (LedgerRows.Any(r => string.IsNullOrWhiteSpace(r.EvidencePointer))) return ActivationReadinessLotVerdict.BlockedByMissingEvidence;
            if (LedgerRows.Any(r => ActivationReadinessText.Contains(r.RefusalTrigger, "feature live") || ActivationReadinessText.Contains(r.RefusalTrigger, "production readiness") || ActivationReadinessText.Contains(r.RefusalTrigger, "sauvegarde officielle"))) return ActivationReadinessLotVerdict.BlockedByLiveClaim;
            if (LedgerRows.Any(r => ActivationReadinessText.Contains(r.RefusalTrigger, "service serveur deduit"))) return ActivationReadinessLotVerdict.BlockedByHiddenServerService;
            return OpenReserves.Count > 0 ? ActivationReadinessLotVerdict.ReadyWithOpenReserves : ActivationReadinessLotVerdict.ReadyForArchitectValidation;
        }
    }

