    internal static class ActivationReadinessText
    {
        public static bool Same(string left, string right) { return string.Equals(left, right, StringComparison.OrdinalIgnoreCase); }
        public static bool Contains(string text, string value) { return (text ?? string.Empty).IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0; }
    }
